/// FUNCTION ///

/**
 * 목록으로 이동
 */
scwin.goList = function () {
    const move_url = "/ui/support/JLDFIL17300.xml";
    $p.url(move_url);
};

/**
 * 저장
 */
scwin.register = function (flag) {
    let q_name = "";
    let in_data_yn = rd_data_yn.getValue();

    //등록자명
    if(in_data_yn === "N") { //담당자정보
        q_name = sel_chrgNm;

        if(!q_name.getValue()) {
            ipt_questrTelNo.setValue("");
            ipt_questrEmail.setValue("");
            alert("'등록자명' 항목을 선택하세요.");
            q_name.focus();
            return;
        }
        dma_QnaInfo.set("questrNm", q_name.getText());

    } else if(in_data_yn === "Y") { //수동입력
        q_name = ipt_chrgNm;

        if(scwin.nullChk(q_name)) {
            return ;
        }
        dma_QnaInfo.set("questrNm", q_name.getValue());

    } else {
        alert("'등록자 정보'를 선택하세요.");
        rd_data_yn.focus();
        return;
    }

    if(scwin.nullChk(ipt_questrTelNo)) {
        return;
    }

    if(scwin.nullChk(ipt_questrEmail)) {
        return;
    }		

    if(scwin.nullChk(sel_quesBzTpCd)) {
        return;
    }

    if(scwin.nullChk(ipt_quesTitle)) {
        return;
    }	

    if(scwin.nullChk(ipt_quesContn)) {
        return;
    }

    if(flag === "I") {
        $c.sbm.execute(sbm_InsertQna);

    } else if(flag === "U") {
        $c.sbm.execute(sbm_UpdateQna);
    }
};

