/**
 * 확약사항 단건 (상세저회)
 */
scwin.searchDetail = function () {

     dma_searchReq.setJSON({
        "userId" : scwin.userId,
        "bzProcsNo" : scwin.bzProcsNo
    });


     const sbmOptions = {
         id : "sbm_commitmentsDetail",
         action : "/api/listing/listinvstg/commitments/select-detail",
         method : "get",
         ref : "dma_searchReq",
         target : "dlt_commitmentsRes2=body.comCommitmentsListResponseDto,dma_commitmentsRes1=body",
         submitDoneHandler : scwin.sbm_commitmentsDetail_submitdone,
         isProcessMsg : false
     };
     $c.sbm.executeDynamic(sbmOptions);
}
